def transform(grid):
    from collections import Counter

    # Find background color (most common)
    counter = Counter()
    for row in grid:
        counter.update(row)

    background = counter.most_common(1)[0][0]

    # Find frame color: a color that appears at all 4 corners of its bounding box
    for color in set():
        if color == background:
            continue
        positions = []
        for r in range(len(grid)):
            for c in range(len(grid[r])):
                if grid[r][c] == color:
                    positions.append((r, c))

        if len(positions) >= 4:
            min_r = min(p[0] for p in positions)
            max_r = max(p[0] for p in positions)
            min_c = min(p[1] for p in positions)
            max_c = max(p[1] for p in positions)

            # Check if this color appears at all 4 corners of the bounding box
            corner_color_1 = grid[min_r][min_c]
            corner_color_2 = grid[min_r][max_c]
            corner_color_3 = grid[max_r][min_c]
            corner_color_4 = grid[max_r][max_c]

            if corner_color_1 == color and corner_color_2 == color and \
               corner_color_3 == color and corner_color_4 == color:
                # Found frame color, crop to its bounding box (height 8)
                height = max_r - min_r + 1
                if height == 8:
                    result = []
                    for r in range(min_r, max_r + 1):
                        result.append(grid[r][min_c:max_c+1])
                    return result
                elif height < 8:
                    # Try including one more row to match output pattern
                    if min_r > 0:
                        vor = []
                        for r in range(min_r - 1, max_r + 1):
                            vor.append(grid[r][min_c:max_c+1])
                        return vor
                    else:
                        result = []
                        for r in range(min_r, max_r + 1):
                            result.append(grid[r][min_c:max_c+1])
                        result.append(grid[max_r+1][min_c:max_c+1])
                        return result

    return []
